(5961025, 870586, 43774, '<td valign="top">Very good photo, I like his expression. But is it full length? I''m not sure.</td>', 'Very good photo, I like his expression. But is it full length? I''m not sure.', '2010-04-21 11:10:34.000000', NULL, 1),
(5961143, 871071, 112013, '<td valign="top">Nice, but a bit blurry in spots which distracts.  5</td>', 'Nice, but a bit blurry in spots which distracts.  5', '2010-04-21 11:45:52.000000', NULL, 1),
(5961144, 871382, 112013, '<td valign="top">...and the pose looks like she is waiting for a train to. A bit to boring. Not catalog, not editorial, but just basically a snapshot to me. 5</td>', '...and the pose looks like she is waiting for a train to. A bit to boring. Not catalog, not editorial, but just basically a snapshot to me. 5', '2010-04-21 11:47:06.000000', NULL, 1),
(5961146, 869693, 112013, '<td valign="top">Eyes are way to intense.  A bit of dear in the headlights. The face is a bit out of focus for me to and I really think this would have been better in sepia.  5</td>', 'Eyes are way to intense.  A bit of dear in the headlights. The face is a bit out of focus for me to and I really think this would have been better in sepia.  5', '2010-04-21 11:48:22.000000', NULL, 1),
(5961148, 871048, 112013, '<td valign="top">Cute but a bit to ordinary for me. 5</td>', 'Cute but a bit to ordinary for me. 5', '2010-04-21 11:48:47.000000', NULL, 1),
(5961151, 871237, 112013, '<td valign="top">There is just to much going on here. To many layers of clothing and mismatched colors and items. Looks like he was standing a props room that exploded. It distracts from the model. 5</td>', 'There is just to much going on here. To many layers of clothing and mismatched colors and items. Looks like he was standing a props room that exploded. It distracts from the model. 5', '2010-04-21 11:50:35.000000', NULL, 1),
(5961157, 871334, 112013, '<td valign="top">I like all of the effort you put in but the dress is just to out of proportion, and I am just not liking the overall newspaper theme. 5</td>', 'I like all of the effort you put in but the dress is just to out of proportion, and I am just not liking the overall newspaper theme. 5', '2010-04-21 11:53:49.000000', NULL, 1),
(5961166, 870840, 112013, '<td valign="top">Shadows, shadows, shadows. It looks like she has been attacked by shadows.  Her face is so shadowed it looks like she has a beard. Im just not getting it. 4</td>', 'Shadows, shadows, shadows. It looks like she has been attacked by shadows.  Her face is so shadowed it looks like she has a beard. Im just not getting it. 4', '2010-04-21 11:56:29.000000', NULL, 1),
(5961169, 871047, 112013, '<td valign="top">Its to bright and over exposed. There are distractions to the right of her right foot that needed to be closed out. Her pose is ordinary with no facial expression at all. 4</td>', 'Its to bright and over exposed. There are distractions to the right of her right foot that needed to be closed out. Her pose is ordinary with no facial expression at all. 4', '2010-04-21 11:57:20.000000', NULL, 1),
(5961176, 871157, 112013, '<td valign="top">Im afraid I dont like this.  It looks like you set up the shot nicely, but that you then asked someone to pose for you while you tested the focus and lighting on your camera. She doesnt look like the model that should be there.  Its also to dark. 4</td>', 'Im afraid I dont like this.  It looks like you set up the shot nicely, but that you then asked someone to pose for you while you tested the focus and lighting on your camera. She doesnt look like the model that should be there.  Its also to dark. 4', '2010-04-21 12:01:22.000000', NULL, 1),
(5961222, 868282, 112013, '<td valign="top">I dont like he is not looking at the camera. He needed to engage with the photographer in order to get a sense of personality and expression. Its a bit blown out. 4</td>', 'I dont like he is not looking at the camera. He needed to engage with the photographer in order to get a sense of personality and expression. Its a bit blown out. 4', '2010-04-21 12:12:36.000000', NULL, 1),
(5961234, 871305, 112013, '<td valign="top">Bad choice of shirt.  It washes him out since his hair is a similar color. He really needed to wear blue in this shot. 5</td>', 'Bad choice of shirt.  It washes him out since his hair is a similar color. He really needed to wear blue in this shot. 5', '2010-04-21 12:15:40.000000', NULL, 1),
(5961241, 869428, 112013, '<td valign="top">You can''t see him and he is not engaging with the photographer. I really don''t see what a modeling agency can do with this shot. It would tell them nothing about this man as an individual. 4</td>', 'You can''t see him and he is not engaging with the photographer. I really don''t see what a modeling agency can do with this shot. It would tell them nothing about this man as an individual. 4', '2010-04-21 12:16:40.000000', NULL, 1),
(5961244, 870539, 112013, '<td valign="top">Im afraid its to much of a snapshot for me and she looks distressed. 4</td>', 'Im afraid its to much of a snapshot for me and she looks distressed. 4', '2010-04-21 12:17:22.000000', NULL, 1),
(5961245, 871187, 112013, '<td valign="top">Im afraid its to much of a snapshot for me and she has no expression in the face. Its also blown out. 4</td>', 'Im afraid its to much of a snapshot for me and she has no expression in the face. Its also blown out. 4', '2010-04-21 12:17:55.000000', NULL, 1),
(5961250, 870826, 112013, '<td valign="top">Ok. hahaa. I gave it a 3.</td>', 'Ok. hahaa. I gave it a 3.', '2010-04-21 12:18:23.000000', NULL, 1),
(5961252, 870004, 112013, '<td valign="top">Lady in Red? Anyway, its just not working for me.  To much of a snapshot and I am not liking the pose, the lighting, or the desat. 3</td>', 'Lady in Red? Anyway, its just not working for me.  To much of a snapshot and I am not liking the pose, the lighting, or the desat. 3', '2010-04-21 12:19:08.000000', NULL, 1),
(5961258, 871073, 112013, '<td valign="top">The shadows in this shot are overwhelming.  Her outfit is dirty at the knees and her eyes are not showing which is very important for a modeling agency to see.  Looks like she would like to be a model though but I have to give this shot a 3.</td>', 'The shadows in this shot are overwhelming.  Her outfit is dirty at the knees and her eyes are not showing which is very important for a modeling agency to see.  Looks like she would like to be a model though but I have to give this shot a 3.', '2010-04-21 12:21:33.000000', NULL, 1),
(5961260, 870070, 112013, '<td valign="top">A nice snapshot but not good for this challenge. 3</td>', 'A nice snapshot but not good for this challenge. 3', '2010-04-21 12:21:50.000000', NULL, 1),
(5961280, 869971, 112013, '<td valign="top">To much of a snapshot for me and I don''t like the desat. 3</td>', 'To much of a snapshot for me and I don''t like the desat. 3', '2010-04-21 12:28:35.000000', NULL, 1),
(5961282, 870518, 112013, '<td valign="top">To much of a snapshot for me. 4</td>', 'To much of a snapshot for me. 4', '2010-04-21 12:29:15.000000', NULL, 1),
