(5961338, 871334, 12796, '<td valign="top">This is cool. But it makes me wonder, was your attempt also aimed at covering everything with newspaper so that it would be impossible to know it was a studio or not? Clever attempt then, and I definitely liked the change.</td>', 'This is cool. But it makes me wonder, was your attempt also aimed at covering everything with newspaper so that it would be impossible to know it was a studio or not? Clever attempt then, and I definitely liked the change.', '2010-04-21 12:54:57.000000', NULL, 1),
(5961401, 870734, 7504, '<td valign="top">Can''t really see his legs with the black on black. Nice black and white though.</td>', 'Can''t really see his legs with the black on black. Nice black and white though.', '2010-04-21 13:18:47.000000', NULL, 1),
