(5961612, 869080, 29293, '<td valign="top">great lighting!</td>', 'great lighting!', '2010-04-21 14:31:53.000000', NULL, 1),
(5961615, 869266, 29293, '<td valign="top">like the unique pose</td>', 'like the unique pose', '2010-04-21 14:32:39.000000', NULL, 1),
