(5962465, 870195, 23484, '<td valign="top">Just give him time, he''ll grow into it.</td>', 'Just give him time, he''ll grow into it.', '2010-04-21 21:10:55.000000', NULL, 1),
(5962466, 869042, 2612, '<td valign="top">I''m a bit confused and unsure how to handle. This is a fantastic full length shot, but does it meet the requirement for a <b>studio</b> shot? After some discussion on the forums, I think I''ll not apply my open perception of a "studio" shot and will simply score this as an excellent full length portrait.</td>', 'I''m a bit confused and unsure how to handle. This is a fantastic full length shot, but does it meet the requirement for a studio shot? After some discussion on the forums, I think I''ll not apply my open perception of a "studio" shot and will simply score this as an excellent full length portrait.', '2010-04-21 21:12:06.000000', NULL, 1),
(5962469, 870865, 23484, '<td valign="top">Nice lighting and composition. Perfect exposure on the face.</td>', 'Nice lighting and composition. Perfect exposure on the face.', '2010-04-21 21:12:44.000000', NULL, 1),
(5962470, 871071, 23484, '<td valign="top">The shallow DOF works very nicely here. Good job.</td>', 'The shallow DOF works very nicely here. Good job.', '2010-04-21 21:13:11.000000', NULL, 1),
(5962474, 871011, 23484, '<td valign="top">I like the light on white.</td>', 'I like the light on white.', '2010-04-21 21:13:58.000000', NULL, 1),
