(5967447, 870701, 51570, '<td valign="top">total hottie. cool photo, like the use of props</td>', 'total hottie. cool photo, like the use of props', '2010-04-25 03:38:04.000000', NULL, 1),
(5967448, 871073, 39349, '<td valign="top">Great attempt this type of shoot; can be a struggle to get right take it from me.<br/> <br/>Things I can point out to help you in the future are:<br/> <br/>Move the model away from the back drop as much as you can. I try to keep them at least 10 feet away from the back of the drop.<br/> <br/>Try to avoid hitting your subject with direct light / flash. Direct light isn''t very flattering and leads to harsh shadows and abrupt fall off. Defusing the light will make this much more appealing. You can do this with just about anything around the house, paper or a white cloth work well. <br/> <br/>If you are using a speed light then there are other options available to you as well. Move it to either side, use bounce or reflectors to direct light, and above all, EXPERIMENT! <br/> <br/>These are just a few pointers to help you on the path. Good luck and keep shooting!</td>', 'Great attempt this type of shoot; can be a struggle to get right take it from me. Things I can point out to help you in the future are: Move the model away from the back drop as much as you can. I try to keep them at least 10 feet away from the back of the drop. Try to avoid hitting your subject with direct light / flash. Direct light isn''t very flattering and leads to harsh shadows and abrupt fall off. Defusing the light will make this much more appealing. You can do this with just about anything around the house, paper or a white cloth work well.  If you are using a speed light then there are other options available to you as well. Move it to either side, use bounce or reflectors to direct light, and above all, EXPERIMENT!  These are just a few pointers to help you on the path. Good luck and keep shooting!', '2010-04-25 03:42:44.000000', NULL, 1),
(5967449, 871369, 39349, '<td valign="top">I''m really diggin this shot.</td>', 'I''m really diggin this shot.', '2010-04-25 03:43:21.000000', NULL, 1),
(5968058, 871334, 47852, '<td valign="top">Hmm... Times Union, Maria College, Armory.  Must be an upstate NY photographer.  Creative, and a welcome changed from the plain white backgrounds.  Nice use of color, pulling out the comics and creating a long page from them.  I know it''s a full length challenge, but I think the photo would work better if it were cut off before the legs.  Something about the tone of her skin on the top/bottom is different and it feels unbalanced.  Good luck!</td>', 'Hmm... Times Union, Maria College, Armory.  Must be an upstate NY photographer.  Creative, and a welcome changed from the plain white backgrounds.  Nice use of color, pulling out the comics and creating a long page from them.  I know it''s a full length challenge, but I think the photo would work better if it were cut off before the legs.  Something about the tone of her skin on the top/bottom is different and it feels unbalanced.  Good luck!', '2010-04-25 14:18:50.000000', NULL, 1),
(5968968, 871499, 61179, '<td valign="top">Focus a little sharper on her face next time, I think.</td>', 'Focus a little sharper on her face next time, I think.', '2010-04-25 22:07:28.000000', NULL, 1),
